export function getTasksForMonth(category, code, monthOffset = 0) {
    let pool = [];
    if (category === 'balanced' || !database[category]) {
        pool = [...rawMedowPoses];
    } else {
        pool = [...database[category]];
        if (pool.length < 30) pool = [...pool, ...rawMedowPoses];
    }

    const targetDate = new Date(currentYear, currentMonth + monthOffset, 1);
    const targetYear = targetDate.getFullYear();
    const targetMonth = targetDate.getMonth();
    const daysInTargetMonth = new Date(targetYear, targetMonth + 1, 0).getDate();

    let seed = 0;
    for (let i = 0; i < code.length; i++) seed += code.charCodeAt(i);
    seed = seed * 31 + targetYear * 12 + targetMonth;

    // Детерминированный Фишер-Йейтс
    const shuffledPool = [...pool];
    for (let i = shuffledPool.length - 1; i > 0; i--) {
        const j = Math.abs((seed * (i + 1) * 17 + i * 7) % (i + 1));
        [shuffledPool[i], shuffledPool[j]] = [shuffledPool[j], shuffledPool[i]];
    }

    // Выбор строго УНИКАЛЬНЫХ поз без повторов
    const usedIds = new Set();
    const uniqueMonthPool = [];
    for (const pose of shuffledPool) {
        if (!usedIds.has(pose.id)) {
            usedIds.add(pose.id);
            uniqueMonthPool.push(pose);
        }
        if (uniqueMonthPool.length >= daysInTargetMonth) break;
    }

    const result = [];
    for (let day = 1; day <= daysInTargetMonth; day++) {
        const goldSecret = goldCardsList.find(g => g.day === day);
        
        if (goldSecret) {
            result.push({
                day: day,
                id: `gold_${day}`,
                title: `${day < 10 ? '0' + day : day}. ${goldSecret.title}`,
                category: "✨ ЗОЛОТАЯ КАРТОЧКА",
                lead: "🎉 СЕКРЕТНЫЙ СЮРПРИЗ",
                roleClass: "role-both",
                img: imgPool[day % imgPool.length],
                task: goldSecret.task,
                tip: goldSecret.tip,
                isGold: true
            });
        } else {
            const pose = uniqueMonthPool[(day - 1) % uniqueMonthPool.length];
            const prelude = preludesList[(day + seed) % preludesList.length];
            const bonus = bonusFinishes[(day * 3 + seed) % bonusFinishes.length];

            const fullComboTask = 
`🔥 РОМАНТИЧЕСКИЙ КОМБО-СЦЕНАРИЙ ВЕЧЕРА:

1️⃣ ЭТАП 1 — ПРЕИСПИСАННАЯ ПРЕЛИДИЯ:
${prelude}

2️⃣ ЭТАП 2 — ОСНОВНАЯ ПОЗА ДНЯ (Medow Club):
${pose.title}
• Вид: ${pose.vidSeksa || 'Сексуальная практика'}
• Положение тела: ${pose.polozhenie || 'Оптимальное'}
• Зона стимуляции: ${pose.stimulyaciya || 'Генитальная'}
• Проникновение: ${pose.proniknovenie || 'Умеренное'}
• Локация: ${pose.raspolozhenie || 'На кровати'}

3️⃣ ЭТАП 3 — ФИНАЛЬНЫЙ БОНУС:
${bonus}`;

            const fullTip = `💡 Аттрибуты Medow Club: Сложность: ${pose.slozhnost || 'Средняя'} | Активность: ${pose.aktivnost || 'Оба'} | Зрительный контакт: ${pose.rawTags.includes('зрительный') ? 'Да' : 'По желанию'}`;

            result.push({
                day: day,
                id: pose.id,
                title: `${day < 10 ? '0' + day : day}. Комбо: ${pose.title.replace(/^Поза #\d+\s*—\s*/, '')}`,
                category: pose.vidSeksa ? pose.vidSeksa.split('.')[0] : 'Комбо-Сет',
                lead: pose.polozhenie ? `👑 ${pose.polozhenie}` : "🤝 Оба на равных",
                roleClass: pose.rawTags.includes("женщина сверху") ? "role-f" : (pose.rawTags.includes("мужчина сзади") ? "role-m" : "role-both"),
                img: pose.img,
                task: fullComboTask,
                tip: fullTip,
                isGold: false
            });
        }
    }
    return result;
}
